from pathlib import Path
import json,hashlib
B=Path(__file__).resolve().parent; ROOT=B.parents[2]; C=B.parent
# Conditions from retained distro tracker/source notes and exact startup/health/maintenance callers.
conditions={
'CVE-2011-3374':('apt-key keyring-URI key retrieval/validation operation.','The supported runtime/startup/health/maintenance command graph does not invoke apt-key or import keys through a keyring URI. Runtime application input never selects an APT repository or key source. Build APT/source-acquisition decisions remain a separate trust boundary; this does not approve arbitrary package installation.'),
'TEMP-0841856-B18BAF':('Bash privilege transition with attacker-selected environment and differing real/effective user IDs (Debian bug841856).','Application and tools entrypoints select Python/Node/.NET directly, without a privileged Bash wrapper. PostgreSQL begins its fixed Bash entrypoint with matching real/effective UID, then gosu sets the user IDs before re-executing it. Public requests cannot supply Bash environment functions or a set-ID wrapper. Tools root preparation is Python, not Bash. This excludes the actual mismatched-identity Bash caller condition, not every local shell exploit.'),
'CVE-2025-6141':('ncurses postprocess_termcap parses a malicious termcap description.','No supported application flow parses a request-selected termcap or provides an interactive terminal. Maintenance query passes psql stdin bytes with stdout PIPE; pg_dump writes a file and pg_restore uses DEVNULL output. Host collation psql uses docker exec -T; PostgreSQL startup SQL uses stdin heredocs. No caller-selected TERM/TERMCAP/TERMINFO is forwarded. This does not claim docker compose run always disables container TTY allocation. Arbitrary interactive operator shells, terminals and custom environment are excluded.'),
'CVE-2025-69720':('infocmp CLI processes the crafted terminal description.','No startup, health or coordinated maintenance caller invokes infocmp; application fields are not passed as terminal descriptions. Other ncurses interfaces are not claimed fixed.'),
'CVE-2026-54411':('pam_userdb password database authentication has a timing discrepancy.','RateFreak local accounts use ASP.NET Identity; no OS PAM login or pam_userdb service is invoked. The supplied PostgreSQL pg_hba rules use SCRAM, not PAM, and the application has no arbitrary SQL/configuration endpoint. An operator-added PAM database authentication rule is outside this exclusion.'),
'CVE-2007-5686':('OS login failure logging records unknown usernames in an insecurely protected log.','The supplied application does not invoke OS login, and its account/authentication records are independent of shadow login failure logging. The container entrypoints do not create a local login service. This is a missing affected caller, not a general claim about all log permissions.'),
'CVE-2024-56433':('Default subordinate UID/GID allocation collides with externally assigned user IDs.','Supported startup and maintenance use fixed image user IDs and the Docker-managed container identity; they do not allocate subordinate UID/GID ranges or invoke newuidmap/newgidmap for user namespaces. Application accounts do not become OS users. Custom namespace/NFS/host account provisioning needs reassessment.'),
'CVE-2026-135901':('newgidmap privileged group-ID mapping helper performs the affected proc/group mapping operation.','No supported container entrypoint, application request, health check or maintenance command invokes newgidmap or allocates a caller-selected user namespace. Fixed gosu execution is a distinct helper and does not route through newgidmap.'),
'TEMP-0628843-DBAD28':('su is used with a shared controlling terminal, allowing the switched user to inject terminal input (Debian bug628843).','No supported flow invokes su or supplies an interactive controlling terminal. PostgreSQL uses the separately reviewed gosu helper; Python storage preparation does not use su. Arbitrary interactive operator switching is outside this exclusion.'),
'TEMP-0517018-A83CE6':('Expert installer no-root option leaves a locally exploitable sysvinit boot/rescue authentication path (Debian bug517018).','These containers execute the supplied service entrypoints directly; they do not boot sysvinit or run an operating-system expert installer/rescue login. sysvinit-utils package presence does not create that caller.'),
'CVE-2022-0563':('chfn/chsh readline handling leaks file content through an affected interactive command.','Application accounts and maintenance do not invoke chfn/chsh or OS user-profile editing. Image users are provisioned at image build; public account fields stay in PostgreSQL. No affected interactive caller is exposed by the supplied runtime command graph.'),
'CVE-2026-3184':('OS login hostname canonicalization affects PAM access-control decisions.','The reference installation exposes no OS login service and does not invoke login for application authentication. The health/maintenance PostgreSQL paths do not use PAM login/RHOST canonicalization. This does not clear a custom shell/SSH/PAM service.'),
'CVE-2026-76642':('mount runs privileged X-mount post-hooks after an external helper fails.','No supported in-container startup/health/maintenance path invokes mount or an external mount helper/post-hook. Compose mounts are performed by the host container engine, outside the affected installed util-linux caller. Root tools preparation uses filesystem APIs, not mount. No assumption that root tools lack capabilities is made.'),
'CVE-2026-78410':('Restricted bind mount X-mount.owner/group/mode handling races an unpinned source.','No supported in-container flow invokes restricted bind mount or X-mount ownership/mode options. The application cannot choose container volume declarations. Docker host mounting is a separate host/container-engine obligation; the installed mount caller is not used.'),
}
ledger=json.loads((ROOT/'docs/release-evidence/2026-11-25-security-followup/advisory-ledger.json').read_text())
rows=[]
for row in ledger:
 if row['disposition']=='open' and row['advisory'] in conditions:
  condition,assessment=conditions[row['advisory']]
  rows.append({'image':row['image'],'image_reference':row['image_reference'],'source':row['source'],'id':row['advisory'],'matches':row['matches'],'condition':condition,'assessment':assessment,'disposition':'conditional-supported-caller-exclusion','evidence':['source-input-hashes.json','postgres-entrypoint.sh','../residual-os/probe-executions.json'],'reassess_if':['Change fixed entrypoint, health check, maintenance, host/TTY, identity, authentication, mount or environment boundary','Enable an interactive shell/login, PAM, user namespaces, operator plugins, custom init scripts or arbitrary SQL/configuration input']})
(B/'assessments.json').write_text(json.dumps(rows,indent=2)+'\n')
files=['deploy/self-host/compose.yaml','deploy/self-host/entrypoint.py','deploy/self-host/maintenance.py','deploy/self-host/database.sql','deploy/self-host/ratefreak.py','src/RateFreak.Infrastructure/DependencyInjection.cs']
hashes={name:hashlib.sha256((C/'source'/name).read_bytes()).hexdigest() for name in files}
hashes['postgres-entrypoint.sh']=hashlib.sha256((C/'postgres-entrypoint.sh').read_bytes()).hexdigest()
(B/'source-input-hashes.json').write_text(json.dumps(hashes,indent=2)+'\n')
print(len(rows),'records',sum(len(x['matches']) for x in rows),'matches')
